mapper.select:

SELECT n.`id`, n.`title`, n.`author`, n.`total_words`, n.`deleted`, n.`user_id`,
       n.`create_time`, n.`update_time`
FROM `novel` n

    n.`user_id` = #{userId}
    AND n.`deleted` = #{deleted}

        AND (n.`title` LIKE CONCAT('%', #{keyword}, '%')
             OR n.`author` LIKE CONCAT('%', #{keyword}, '%'))


        AND EXISTS (
            SELECT 1 FROM `novel_tag_relation` r
            WHERE r.`novel_id` = n.`id`
              AND r.`tag_id` = #{tagId}
              AND r.`user_id` = #{userId}
        )


ORDER BY n.`id` DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM `novel` n

    n.`user_id` = #{userId}
    AND n.`deleted` = #{deleted}

        AND (n.`title` LIKE CONCAT('%', #{keyword}, '%')
             OR n.`author` LIKE CONCAT('%', #{keyword}, '%'))


        AND EXISTS (
            SELECT 1 FROM `novel_tag_relation` r
            WHERE r.`novel_id` = n.`id`
              AND r.`tag_id` = #{tagId}
              AND r.`user_id` = #{userId}
        )
